SELECT count(*) from recipe r
join member m on r.member_id = m.member_id
left join recipe_category rc on r.recipe_id = rc.recipe_id
left join category c on rc.category_id = c.category_id
where 1=1

    AND (
        r.title Like concat('%',#{keyword}, '%')
        OR m.nickname LIKE concat('%',#{keyword}, '%')
    )


AND c.category_name = #{category}



    AND r.status = #{status}



    AND r.recommend = #{recommend}

SELECT
    r.*,           
    c.category_name
FROM recipe_view r
JOIN recipe_category rc ON r.recipe_id = rc.recipe_id
JOIN category c ON rc.category_id = c.category_id
WHERE 1=1


    AND (
        r.title LIKE CONCAT('%', #{keyword}, '%')
        OR r.nickname LIKE CONCAT('%', #{keyword}, '%')
    )



    AND c.category_name = #{category}



    AND r.status = #{status}



    AND r.recommend = #{recommend}


ORDER BY r.recipe_id DESC
LIMIT #{size} OFFSET #{offset}

